	s.AddTool(
		mcplib.NewTool("zones_bot-management_for-a-zone-update-config",
			mcplib.WithDescription("Updates the Bot Management configuration for a zone. This API is used to update: - **Bot Fight Mode** - **Super Bot Fight Mode** - **Bot Management for Enterprise** See [Bot Plans](https://developers.cloudflare.com/bots/plans/) for more information on the different plans If you recently upgraded or downgraded your plan, refer to the following examples to clean up old configurations. Copy and paste the example body to remove old zone configurations based on your current plan. #### Clean up configuration for Bot Fight Mode plan ```json { 'sbfm_likely_automated': 'allow', 'sbfm_definitely_automated': 'allow', 'sbfm_verified_bots': 'allow', 'sbfm_static_resource_protection': false, 'optimize_wordpress': false, 'suppress_session_score': false } ``` #### Clean up configuration for SBFM Pro plan ```json { 'sbfm_likely_automated': 'allow', 'fight_mode': false } ``` #### Clean up configuration for SBFM Biz plan ```json { 'fight_mode': false } ``` #### Clean up configuration for BM Enterprise Subscription plan It is strongly recommended that you ensure you have [custom rules](https://developers.cloudflare.com/waf/custom-rules/) in place to protect your zone before disabling the SBFM rules. Without these protections, your zone is vulnerable to attacks. ```json { 'sbfm_likely_automated': 'allow', 'sbfm_definitely_automated': 'allow', 'sbfm_verified_bots': 'allow', 'sbfm_static_resource_protection': false, 'optimize_wordpress': false, 'fight_mode': false } ```. Required: zone_id. Returns the updated BotManagementBotManagementResponseBody."),
			mcplib.WithString("zone_id", mcplib.Required(), mcplib.Description("Zone id")),
			mcplib.WithOpenWorldHintAnnotation(true),
		),
		makeAPIHandler("PUT", "/zones/{zone_id}/bot_management", []mcpParamBinding{{PublicName: "zone_id", WireName: "zone_id", Location: "path"}, }, []string{"zone_id", }),
	)
	s.AddTool(
		mcplib.NewTool("zones_bot-management_zone-feedback-create",
			mcplib.WithDescription("Submit a feedback report for the specified zone. Use `type` to indicate whether the report is a false positive (good traffic flagged as bot) or a false negative (bot traffic missed). Furthermore, you can also use `expression` as a wirefilter to identify the affected traffic sample. See more accepted API fields and expression types at https://developers.cloudflare.com/bots/concepts/feedback-loop/#api-fields and https://developers.cloudflare.com/bots/concepts/feedback-loop/#expression-fields, respectively. Required: zone_id, description, expression, first_request_seen_at, last_request_seen_at, requests, requests_by_attribute, requests_by_score, requests_by_score_src, type. Optional: created_at, subtype."),
			mcplib.WithString("zone_id", mcplib.Required(), mcplib.Description("Zone id")),
			mcplib.WithString("created_at", mcplib.Description("Created at")),
			mcplib.WithString("description", mcplib.Required(), mcplib.Description("Description")),
			mcplib.WithString("expression", mcplib.Required(), mcplib.Description("Wirefilter expression describing the traffic being reported.")),
			mcplib.WithString("first_request_seen_at", mcplib.Required(), mcplib.Description("First request seen at")),
			mcplib.WithString("last_request_seen_at", mcplib.Required(), mcplib.Description("Last request seen at")),
			mcplib.WithString("requests", mcplib.Required(), mcplib.Description("Requests")),
			mcplib.WithString("requests_by_attribute", mcplib.Required(), mcplib.Description("Top attributes contributing to the feedback sample. Keys include topASNs, topCountries, topHosts, topIPs,...")),
			mcplib.WithString("requests_by_score", mcplib.Required(), mcplib.Description("Map of bot scores (1-99) to request counts. Sum must equal `requests`.")),
			mcplib.WithString("requests_by_score_src", mcplib.Required(), mcplib.Description("Map of score source to request counts. Sum must equal `requests`.")),
			mcplib.WithString("subtype", mcplib.Description("Subtype")),
			mcplib.WithString("type", mcplib.Required(), mcplib.Description("Type of feedback report.")),
			mcplib.WithDestructiveHintAnnotation(false),
			mcplib.WithOpenWorldHintAnnotation(true),
		),
		makeAPIHandler("POST", "/zones/{zone_id}/bot_management/feedback", []mcpParamBinding{{PublicName: "zone_id", WireName: "zone_id", Location: "path"},{PublicName: "created_at", WireName: "created_at", Location: "body"},{PublicName: "description", WireName: "description", Location: "body"},{PublicName: "expression", WireName: "expression", Location: "body"},{PublicName: "first_request_seen_at", WireName: "first_request_seen_at", Location: "body"},{PublicName: "last_request_seen_at", WireName: "last_request_seen_at", Location: "body"},{PublicName: "requests", WireName: "requests", Location: "body"},{PublicName: "requests_by_attribute", WireName: "requests_by_attribute", Location: "body"},{PublicName: "requests_by_score", WireName: "requests_by_score", Location: "body"},{PublicName: "requests_by_score_src", WireName: "requests_by_score_src", Location: "body"},{PublicName: "subtype", WireName: "subtype", Location: "body"},{PublicName: "type", WireName: "type", Location: "body"}, }, []string{"zone_id", }),
	)
